template<typename ETR_REAL>
struct solve_h_ida_t {
  SolveD_HD_Result<ETR_REAL> operator()( const ETR_REAL Kd, const ETR_REAL Kg, const ETR_REAL h0, const ETR_REAL d0, const etr::Array<ETR_REAL, etr::Buffer<ETR_REAL>> g ) const {
     etr::Integer n;
     SolveD_HD_Result<ETR_REAL> out;
     EquationParamsIda<ETR_REAL> params;
     etr::uniroot_result ur;
     ETR_REAL d_sol;
    etr::current_line() = "tsf: ida.R:35 (solve_h_ida): n <- length(g)";
    n = etr::length(g);
    etr::current_line() = "tsf: ida.R:37 (solve_h_ida): out$d <- numeric(n)";
    out.d = etr::numeric_of<ETR_REAL>(n);
    etr::current_line() = "tsf: ida.R:38 (solve_h_ida): out$hd <- numeric(n)";
    out.hd = etr::numeric_of<ETR_REAL>(n);
    etr::current_line() = "tsf: ida.R:41 (solve_h_ida): params$Kd <- Kd";
    params.Kd = Kd;
    etr::current_line() = "tsf: ida.R:42 (solve_h_ida): params$Kg <- Kg";
    params.Kg = Kg;
    etr::current_line() = "tsf: ida.R:43 (solve_h_ida): params$h0 <- h0";
    params.h0 = h0;
    etr::current_line() = "tsf: ida.R:44 (solve_h_ida): params$d0 <- d0";
    params.d0 = d0;
    etr::current_line() = "tsf: ida.R:46 (solve_h_ida): for (i in 1L : n)";
    for(const auto i : etr::colon(etr::Integer(1), n)) {
     etr::current_line() = "tsf: ida.R:47 (solve_h_ida): params$g <- g[i]";
     params.g = etr::subset(g, i);
     etr::current_line() = "tsf: ida.R:48 (solve_h_ida): ur <- uniroot(equation_h_ida, c(1e-20, h0), 1e-14, 200.0, params)";
     ur = etr::uniroot(loss_fct_ida_a2a_impl::equation_h_ida_t<ETR_REAL>{}, etr::c(ETR_REAL(1e-20), h0), ETR_REAL(1e-14), ETR_REAL(200.0), params);
     etr::current_line() = "tsf: ida.R:49 (solve_h_ida): if (is.na(ur$root) || ur$root <= 0.0) {...} else {...}";
     if (static_cast<bool>(etr::isNA(ur.root)) || static_cast<bool>(ur.root <= ETR_REAL(0.0))) {
         etr::current_line() = "tsf: ida.R:50 (solve_h_ida): out$d[i] <- NA";
         etr::subset_assign(out.d, ETR_REAL::NA(), i);
         etr::current_line() = "tsf: ida.R:51 (solve_h_ida): out$hd[i] <- NA";
         etr::subset_assign(out.hd, ETR_REAL::NA(), i);
     } else {
         etr::current_line() = "tsf: ida.R:53 (solve_h_ida): d_sol <- d0 / (1.0 + Kd * ur$root)";
         d_sol = d0 / (ETR_REAL(1.0) + Kd * ur.root);
         etr::current_line() = "tsf: ida.R:54 (solve_h_ida): if (d_sol < 0.0) {...} else {...}";
         if (static_cast<bool>(d_sol < ETR_REAL(0.0))) {
             etr::current_line() = "tsf: ida.R:55 (solve_h_ida): out$d[i] <- NA";
             etr::subset_assign(out.d, ETR_REAL::NA(), i);
             etr::current_line() = "tsf: ida.R:56 (solve_h_ida): out$hd[i] <- NA";
             etr::subset_assign(out.hd, ETR_REAL::NA(), i);
         } else {
             etr::current_line() = "tsf: ida.R:58 (solve_h_ida): out$d[i] <- d_sol";
             etr::subset_assign(out.d, d_sol, i);
             etr::current_line() = "tsf: ida.R:59 (solve_h_ida): out$hd[i] <- Kd * ur$root * d_sol";
             etr::subset_assign(out.hd, Kd * ur.root * d_sol, i);         
         };     
     };
    }
    etr::current_line() = "tsf: ida.R:63 (solve_h_ida): return(out)";
    return(out);
  }
};
