template<typename ETR_REAL>
struct equation_h_ida_t {
  ETR_REAL operator()( ETR_REAL h, EquationParamsIda<ETR_REAL> params ) const {
     ETR_REAL denom_Kd;
     ETR_REAL h_d;
     ETR_REAL h_g;
     ETR_REAL denom_Kg;
    etr::current_line() = "tsf: ida.R:13 (equation_h_ida): if (h <= 0.0) {...}";
    if (static_cast<bool>(h <= ETR_REAL(0.0))) {
        etr::current_line() = "tsf: ida.R:14 (equation_h_ida): return(1.797693e+308)";
        return(etr::Evaluate(ETR_REAL(1.797693e+308)));
    };
    etr::current_line() = "tsf: ida.R:16 (equation_h_ida): denom_Kd <- 1.0 + params$Kd * h";
    denom_Kd = ETR_REAL(1.0) + params.Kd * h;
    etr::current_line() = "tsf: ida.R:17 (equation_h_ida): h_d <- (params$Kd * h * params$d0) / denom_Kd";
    h_d = (params.Kd * h * params.d0) / denom_Kd;
    etr::current_line() = "tsf: ida.R:18 (equation_h_ida): h_g <- 0.0";
    h_g = ETR_REAL(0.0);
    etr::current_line() = "tsf: ida.R:19 (equation_h_ida): if (params$g > 0.0) {...}";
    if (static_cast<bool>(params.g > ETR_REAL(0.0))) {
        etr::current_line() = "tsf: ida.R:20 (equation_h_ida): denom_Kg <- 1.0 + params$Kg * h";
        denom_Kg = ETR_REAL(1.0) + params.Kg * h;
        etr::current_line() = "tsf: ida.R:21 (equation_h_ida): h_g <- (params$Kg * h * params$g) / denom_Kg";
        h_g = (params.Kg * h * params.g) / denom_Kg;
    };
    etr::current_line() = "tsf: ida.R:23 (equation_h_ida): return(h + h_d + h_g - params$h0)";
    return(etr::Evaluate(h + h_d + h_g - params.h0));
  }
};
